insert into public.categories (id, parent_id, slug, name, description, sort_order) values ('0da81f8c-402b-5bb1-828d-d474dcc136c3', null, '{"nl":"stadsfietsen","en":"city-bikes"}'::jsonb, '{"nl":"Stadsfietsen","en":"City bikes"}'::jsonb, '{"nl":"Degelijke stadsfietsen voor dagelijks gebruik: naar werk, college of de markt. Met verlichting, drager en slot-voorbereiding.","en":"Dependable city bikes for everyday riding: to work, class or the market. With lights, rack and lock mounts."}'::jsonb, 1);
insert into public.categories (id, parent_id, slug, name, description, sort_order) values ('11e913f9-dd5f-5b9d-b576-54a2b9773c9f', null, '{"nl":"e-bikes","en":"e-bikes"}'::jsonb, '{"nl":"E-bikes","en":"E-bikes"}'::jsonb, '{"nl":"Elektrische fietsen met betrouwbare middenmotoren en accu''s tot 130 km bereik. Proefrit? Kom langs bij het Vondelpark.","en":"Electric bikes with reliable mid-drive motors and batteries up to 130 km of range. Test ride? Visit us at the Vondelpark."}'::jsonb, 2);
insert into public.categories (id, parent_id, slug, name, description, sort_order) values ('16215d93-7815-5527-b7ae-d14229f1e027', null, '{"nl":"racefietsen","en":"road-bikes"}'::jsonb, '{"nl":"Racefietsen","en":"Road bikes"}'::jsonb, '{"nl":"Lichte racefietsen voor de dijken en duinen. Van instapmodel tot carbon klimgeit.","en":"Lightweight road bikes for dikes and dunes. From entry level to carbon climbing machines."}'::jsonb, 3);
insert into public.categories (id, parent_id, slug, name, description, sort_order) values ('2390b79e-8446-57a5-8125-d42a39306a0e', null, '{"nl":"kinderfietsen","en":"kids-bikes"}'::jsonb, '{"nl":"Kinderfietsen","en":"Kids'' bikes"}'::jsonb, '{"nl":"Veilige kinderfietsen van 16 tot 24 inch, met lage instap en stevige spatborden.","en":"Safe kids'' bikes from 16 to 24 inch, with low step-through frames and sturdy mudguards."}'::jsonb, 4);
insert into public.categories (id, parent_id, slug, name, description, sort_order) values ('42a6e887-5474-5062-ad8d-85c9575e54b4', null, '{"nl":"accessoires","en":"accessories"}'::jsonb, '{"nl":"Accessoires","en":"Accessories"}'::jsonb, '{"nl":"Alles voor onderweg: helmen, sloten, verlichting en tassen.","en":"Everything for the road: helmets, locks, lighting and bags."}'::jsonb, 5);
insert into public.categories (id, parent_id, slug, name, description, sort_order) values ('88540cb4-e2ff-5831-b41d-b13ab90a52f7', null, '{"nl":"onderdelen","en":"parts"}'::jsonb, '{"nl":"Onderdelen","en":"Parts"}'::jsonb, '{"nl":"Banden, zadels, kettingen en pedalen — de onderdelen die het vaakst aan vervanging toe zijn.","en":"Tyres, saddles, chains and pedals — the parts that wear out first."}'::jsonb, 6);
insert into public.categories (id, parent_id, slug, name, description, sort_order) values ('e6b3d4d2-353f-55d7-acc6-8b7c34d314c8', null, '{"nl":"boeken-kaarten","en":"books-maps"}'::jsonb, '{"nl":"Boeken & kaarten","en":"Books & maps"}'::jsonb, '{"nl":"Fietsgidsen en routekaarten voor Nederland en daarbuiten. Boeken vallen onder het 9%-btw-tarief.","en":"Cycling guides and route maps for the Netherlands and beyond. Books fall under the reduced 9% VAT rate."}'::jsonb, 7);
insert into public.categories (id, parent_id, slug, name, description, sort_order) values ('f5086abd-a28d-5e5a-b1b5-c158a4615302', '42a6e887-5474-5062-ad8d-85c9575e54b4', '{"nl":"helmen","en":"helmets"}'::jsonb, '{"nl":"Helmen","en":"Helmets"}'::jsonb, '{"nl":"Fietshelmen voor stad, race en kinderen — allemaal met NTA-keurmerk (demo).","en":"Bike helmets for city, road and kids — all certified (demo)."}'::jsonb, 1);
