insert into public.products (id, category_id, slug, name, description, specs, brand, vat_rate, base_price_cents, status, created_at) values ('02757a18-6571-53b9-91b9-44f9a0ec5727', '0da81f8c-402b-5bb1-828d-d474dcc136c3', '{"nl":"vondel-stadsrijder-3","en":"vondel-city-rider-3"}'::jsonb, '{"nl":"Vondel Stadsrijder 3","en":"Vondel City Rider 3"}'::jsonb, '{"nl":"Onze meest verkochte stadsfiets: onverwoestbaar stalen frame, drie versnellingen en altijd-aan naafdynamoverlichting. Specificaties — type: Unisex, versnellingen: 3, wielmaat: 28 inch, framemateriaal: Staal. Geleverd met twee jaar Vondel-garantie en gratis eerste servicebeurt in onze werkplaats aan het Vondelpark.","en":"Our best-selling city bike: indestructible steel frame, three gears and always-on hub dynamo lights. Specifications — type: Unisex, gears: 3, wheel size: 28 inch, frame material: Steel. Comes with a two-year Vondel warranty and a free first service in our workshop next to the Vondelpark."}'::jsonb, '[{"label":{"nl":"Merk","en":"Brand"},"value":{"nl":"Vondel Cycles","en":"Vondel Cycles"}},{"label":{"nl":"Type","en":"Type"},"value":{"nl":"Unisex","en":"Unisex"}},{"label":{"nl":"Versnellingen","en":"Gears"},"value":{"nl":"3","en":"3"}},{"label":{"nl":"Wielmaat","en":"Wheel size"},"value":{"nl":"28 inch","en":"28 inch"}},{"label":{"nl":"Framemateriaal","en":"Frame material"},"value":{"nl":"Staal","en":"Steel"}},{"label":{"nl":"Gewicht","en":"Weight"},"value":{"nl":"18,5 kg","en":"18.5 kg"}}]'::jsonb, 'Vondel Cycles', 21, 45372, 'active', '2026-03-06T00:00:00.000Z');
