insert into public.products (id, category_id, slug, name, description, specs, brand, vat_rate, base_price_cents, status, created_at) values ('d8778efa-f1f4-5f6f-83d0-a25f3a82d4e1', '0da81f8c-402b-5bb1-828d-d474dcc136c3', '{"nl":"windkracht-vouwfiets-v20","en":"windkracht-folding-bike-v20"}'::jsonb, '{"nl":"Windkracht Vouwfiets V20","en":"Windkracht Folding Bike V20"}'::jsonb, '{"nl":"In tien seconden gevouwen en gratis mee in de trein: de ideale combinatie met een OV-abonnement. Specificaties — type: Unisex, versnellingen: 7, wielmaat: 20 inch, framemateriaal: Aluminium. Geleverd met twee jaar Vondel-garantie en gratis eerste servicebeurt in onze werkplaats aan het Vondelpark.","en":"Folds in ten seconds and travels free on the train: the perfect match for a transit pass. Specifications — type: Unisex, gears: 7, wheel size: 20 inch, frame material: Aluminium. Comes with a two-year Vondel warranty and a free first service in our workshop next to the Vondelpark."}'::jsonb, '[{"label":{"nl":"Merk","en":"Brand"},"value":{"nl":"Windkracht","en":"Windkracht"}},{"label":{"nl":"Type","en":"Type"},"value":{"nl":"Unisex","en":"Unisex"}},{"label":{"nl":"Versnellingen","en":"Gears"},"value":{"nl":"7","en":"7"}},{"label":{"nl":"Wielmaat","en":"Wheel size"},"value":{"nl":"20 inch","en":"20 inch"}},{"label":{"nl":"Framemateriaal","en":"Frame material"},"value":{"nl":"Aluminium","en":"Aluminium"}},{"label":{"nl":"Gewicht","en":"Weight"},"value":{"nl":"12,7 kg","en":"12.7 kg"}}]'::jsonb, 'Windkracht', 21, 47851, 'active', '2026-05-10T00:00:00.000Z');
