insert into public.products (id, category_id, slug, name, description, specs, brand, vat_rate, base_price_cents, status, created_at) values ('a6c27600-3a74-55b4-97b6-4d29535af3f4', '11e913f9-dd5f-5b9d-b576-54a2b9773c9f', '{"nl":"grachtenfiets-e-oma","en":"grachtenfiets-e-granny"}'::jsonb, '{"nl":"Grachtenfiets E-Oma","en":"Grachtenfiets E-Granny"}'::jsonb, '{"nl":"De vertrouwde omafiets, nu met stille voorwielmotor en accu verstopt in de bagagedrager. Specificaties — type: Dames, versnellingen: 3, wielmaat: 28 inch, framemateriaal: Staal, accubereik: Tot 50 km. Geleverd met twee jaar Vondel-garantie en gratis eerste servicebeurt in onze werkplaats aan het Vondelpark.","en":"The trusted granny bike, now with a silent front-wheel motor and the battery hidden in the rear rack. Specifications — type: Women, gears: 3, wheel size: 28 inch, frame material: Steel, battery range: Up to 50 km. Comes with a two-year Vondel warranty and a free first service in our workshop next to the Vondelpark."}'::jsonb, '[{"label":{"nl":"Merk","en":"Brand"},"value":{"nl":"Grachtenfiets","en":"Grachtenfiets"}},{"label":{"nl":"Type","en":"Type"},"value":{"nl":"Dames","en":"Women"}},{"label":{"nl":"Versnellingen","en":"Gears"},"value":{"nl":"3","en":"3"}},{"label":{"nl":"Wielmaat","en":"Wheel size"},"value":{"nl":"28 inch","en":"28 inch"}},{"label":{"nl":"Framemateriaal","en":"Frame material"},"value":{"nl":"Staal","en":"Steel"}},{"label":{"nl":"Accubereik","en":"Battery range"},"value":{"nl":"Tot 50 km","en":"Up to 50 km"}},{"label":{"nl":"Gewicht","en":"Weight"},"value":{"nl":"24,3 kg","en":"24.3 kg"}}]'::jsonb, 'Grachtenfiets', 21, 132149, 'active', '2026-04-26T00:00:00.000Z');
