insert into public.products (id, category_id, slug, name, description, specs, brand, vat_rate, base_price_cents, status, created_at) values ('30d9f23a-9a13-5d84-ac55-792a7e30fe41', '11e913f9-dd5f-5b9d-b576-54a2b9773c9f', '{"nl":"windkracht-e-trekking-130","en":"windkracht-e-trekking-130"}'::jsonb, '{"nl":"Windkracht E-Trekking 130","en":"Windkracht E-Trekking 130"}'::jsonb, '{"nl":"Trekking-e-bike met 130 km bereik, afgemonteerd met tassendragers en verende voorvork. Specificaties — type: Unisex, versnellingen: 11, wielmaat: 28 inch, framemateriaal: Aluminium, accubereik: Meer dan 100 km. Geleverd met twee jaar Vondel-garantie en gratis eerste servicebeurt in onze werkplaats aan het Vondelpark.","en":"Trekking e-bike with 130 km of range, fitted with pannier racks and a suspension fork. Specifications — type: Unisex, gears: 11, wheel size: 28 inch, frame material: Aluminium, battery range: Over 100 km. Comes with a two-year Vondel warranty and a free first service in our workshop next to the Vondelpark."}'::jsonb, '[{"label":{"nl":"Merk","en":"Brand"},"value":{"nl":"Windkracht","en":"Windkracht"}},{"label":{"nl":"Type","en":"Type"},"value":{"nl":"Unisex","en":"Unisex"}},{"label":{"nl":"Versnellingen","en":"Gears"},"value":{"nl":"11","en":"11"}},{"label":{"nl":"Wielmaat","en":"Wheel size"},"value":{"nl":"28 inch","en":"28 inch"}},{"label":{"nl":"Framemateriaal","en":"Frame material"},"value":{"nl":"Aluminium","en":"Aluminium"}},{"label":{"nl":"Accubereik","en":"Battery range"},"value":{"nl":"Meer dan 100 km","en":"Over 100 km"}},{"label":{"nl":"Gewicht","en":"Weight"},"value":{"nl":"25,5 kg","en":"25.5 kg"}}]'::jsonb, 'Windkracht', 21, 247851, 'active', '2025-06-15T00:00:00.000Z');
