insert into public.products (id, category_id, slug, name, description, specs, brand, vat_rate, base_price_cents, status, created_at) values ('6b9e59e4-28a5-50f7-890d-7d587baef0f5', '11e913f9-dd5f-5b9d-b576-54a2b9773c9f', '{"nl":"noordwiel-e-singel","en":"noordwiel-e-singel"}'::jsonb, '{"nl":"Noordwiel E-Singel","en":"Noordwiel E-Singel"}'::jsonb, '{"nl":"Puristische e-bike die je nauwelijks van een gewone fiets onderscheidt — tot je de motor inschakelt. Specificaties — type: Unisex, versnellingen: 1 (singlespeed), wielmaat: 28 inch, framemateriaal: Aluminium, accubereik: Tot 50 km. Geleverd met twee jaar Vondel-garantie en gratis eerste servicebeurt in onze werkplaats aan het Vondelpark.","en":"A purist e-bike you can barely tell from a regular bike — until you switch on the motor. Specifications — type: Unisex, gears: 1 (single speed), wheel size: 28 inch, frame material: Aluminium, battery range: Up to 50 km. Comes with a two-year Vondel warranty and a free first service in our workshop next to the Vondelpark."}'::jsonb, '[{"label":{"nl":"Merk","en":"Brand"},"value":{"nl":"Noordwiel","en":"Noordwiel"}},{"label":{"nl":"Type","en":"Type"},"value":{"nl":"Unisex","en":"Unisex"}},{"label":{"nl":"Versnellingen","en":"Gears"},"value":{"nl":"1 (singlespeed)","en":"1 (single speed)"}},{"label":{"nl":"Wielmaat","en":"Wheel size"},"value":{"nl":"28 inch","en":"28 inch"}},{"label":{"nl":"Framemateriaal","en":"Frame material"},"value":{"nl":"Aluminium","en":"Aluminium"}},{"label":{"nl":"Accubereik","en":"Battery range"},"value":{"nl":"Tot 50 km","en":"Up to 50 km"}},{"label":{"nl":"Gewicht","en":"Weight"},"value":{"nl":"16,8 kg","en":"16.8 kg"}}]'::jsonb, 'Noordwiel', 21, 181736, 'active', '2025-06-30T00:00:00.000Z');
