insert into public.products (id, category_id, slug, name, description, specs, brand, vat_rate, base_price_cents, status, created_at) values ('7944143d-a04c-5f08-8852-0ed1b44731bc', 'e6b3d4d2-353f-55d7-acc6-8b7c34d314c8', '{"nl":"knooppunten-van-nederland-50-routes","en":"junction-routes-of-the-netherlands-50-rides"}'::jsonb, '{"nl":"Knooppunten van Nederland — 50 routes","en":"Junction Routes of the Netherlands — 50 rides"}'::jsonb, '{"nl":"De vijftig mooiste knooppuntroutes, van Waddenkust tot Limburgse heuvels, met koffiestops. Geleverd met twee jaar Vondel-garantie en gratis eerste servicebeurt in onze werkplaats aan het Vondelpark.","en":"The fifty most beautiful junction-network routes, from the Wadden coast to the Limburg hills, with coffee stops. Comes with a two-year Vondel warranty and a free first service in our workshop next to the Vondelpark."}'::jsonb, '[{"label":{"nl":"Merk","en":"Brand"},"value":{"nl":"Veluwe Uitgevers","en":"Veluwe Uitgevers"}},{"label":{"nl":"Gewicht","en":"Weight"},"value":{"nl":"0,48 kg","en":"0.48 kg"}},{"label":{"nl":"Pagina''s","en":"Pages"},"value":{"nl":"224","en":"224"}},{"label":{"nl":"Taal","en":"Language"},"value":{"nl":"Nederlands","en":"Dutch"}}]'::jsonb, 'Veluwe Uitgevers', 9, 2293, 'active', '2025-10-11T00:00:00.000Z');
